import {groupIssues} from './issue-alerts.js?v=history-20261017';
import {formatTime} from './collection-time.js?v=20261017';
import {workbook} from './xlsx.js?v=20261015-template';
export function historyAccount(portal,username){if(!portal||!username)throw Error('Sign in to access your history.');return JSON.stringify([portal,username]);}
export function alertHistory(issues,summary,time=Date.now()){return [{type:'Scan summary',time,user:'',editor:'',layer:'All selected monitoring layers',url:'',globalId:'',objectId:'',boundary:'See alert rows for boundary',fields:[{name:'',label:'',missing:''}],comment:summary,coverage:summary},...groupIssues(issues).map(issue=>({type:'Missing attributes',time,user:issue.user,editor:'',layer:issue.layer,url:issue.url,globalId:issue.globalId||'',objectId:issue.objectId,boundary:issue.boundary||'All accessible areas',collectedAt:issue.collectedAt,editedAt:issue.editedAt,dateZoneUnknown:issue.dateZoneUnknown,fields:issue.checkedAttributes?.filter(f=>f.kind).map(f=>({name:f.name,label:f.label,missing:f.kind}))||issue.missingFields.map(f=>({name:f.name,label:f.label,missing:f.kind})),comment:alertComment(issue),coverage:summary}))];}
function alertComment(issue){return 'Missing attributes: '+(issue.checkedAttributes?.filter(f=>f.kind).map(f=>f.label)||issue.fields).join(', ')+'.';}
export function historyRows(events,term=''){const q=term.trim().toLowerCase(),rows=[];for(const event of events)for(const field of event.fields||[]){const row=[formatTime(event.time),event.type,event.user,event.editor||'',event.layer,event.globalId,event.objectId,field.label||field.name,field.name,field.missing||'',field.before??'',field.after??'',formatTime(event.collectedAt,event.dateZoneUnknown),formatTime(event.editedAt,event.dateZoneUnknown),event.boundary,event.comment,event.coverage||'',event.url];if(!q||row.some(v=>String(v??'').toLowerCase().includes(q)))rows.push(row);}return rows;}
export const historyHeaders=['Recorded time (Kigali)','Event','Surveyor username','Submitted by','Layer','Global ID','Object ID','Attribute','Service field','Missing value','Before edit','After edit','Collection / creation time','Last edited time','Monitoring boundary','Comment / result','Scan coverage','Service layer'];
let database;
function db(){return database??=(new Promise((resolve,reject)=>{const request=indexedDB.open('reg-monitor-history',1);request.onupgradeneeded=()=>{const store=request.result.createObjectStore('events',{keyPath:'id',autoIncrement:true});store.createIndex('account','account');};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);request.onblocked=()=>reject(Error('Close other app tabs to open history storage.'));})).catch(e=>{database=null;throw e;});}
export async function storeHistory(account,events){if(!events.length)return;const database=await db();return new Promise((resolve,reject)=>{const tx=database.transaction('events','readwrite');for(const event of events)tx.objectStore('events').add({...event,account});tx.oncomplete=()=>resolve();tx.onabort=()=>reject(tx.error||Error('History could not be stored.'));tx.onerror=()=>{};});}
export async function readHistory(account){const database=await db();return new Promise((resolve,reject)=>{const request=database.transaction('events').objectStore('events').index('account').getAll(account);request.onsuccess=()=>resolve(request.result.sort((a,b)=>b.time-a.time||b.id-a.id));request.onerror=()=>reject(request.error);});}
export function attachHistory({$,state,auth,makeTable}){let shownAccount=null,busy=false;const key=()=>{const api=auth();return historyAccount(api.portal,state.user.username);};const status=t=>$('history-status').textContent=t;
 async function display(){const account=key(),events=await readHistory(account);if(key()!==account)return;shownAccount=account;const rows=historyRows(events,$('history-search').value);$('history-results').replaceChildren(rows.length?makeTable(['Recorded (Kigali)','Username','Field missed / edited','Missing value / result','Layer','Global ID','Comment'],rows.slice(0,200).map(row=>[row[0],row[2]||row[3],row[7]||'—',row[1]==='Missing attributes'?row[9]:row[1],row[4],row[5],row[15]])):document.createTextNode('No history matches. History begins with checks and edits recorded after this update.'));status(events.length+' stored history event(s); '+rows.length+' matching field row(s). Showing the first '+Math.min(rows.length,200)+'. Excel includes every matching row.');}
 async function run(task){if(busy)return;busy=true;$('history-refresh').disabled=true;$('history-export').disabled=true;try{await task();}catch(e){status('History error: '+e.message);}finally{busy=false;$('history-refresh').disabled=false;$('history-export').disabled=false;}}
 $('history-refresh').onclick=()=>run(display);$('history-search').onchange=()=>run(display);
 $('history-export').onclick=()=>run(async()=>{const account=key(),events=await readHistory(account);if(key()!==account)return;const rows=historyRows(events,$('history-search').value);if(!rows.length)throw Error('No matching field history to export. Run Check now first.');const sheets=[];for(let offset=0;offset<rows.length;offset+=1048575)sheets.push({name:'History '+(sheets.length+1),rows:[historyHeaders,...rows.slice(offset,offset+1048575)]});sheets.push({name:'Report information',rows:[['Property','Value'],['Portal',state.api.portal],['Account',state.user.username],['Exported UTC',new Date().toISOString()],['Filter',$('history-search').value],['Field rows',rows.length],['Storage','This browser and website only. Clearing browser site data removes history.'],['Scope','Observed alert comments and verified edits recorded after the history feature was added. No earlier checks are reconstructed.'],['Times','Kigali UTC+02:00, except date fields explicitly marked timezone unknown.'],['Repeated alerts','Each completed scan stores its observed missing attributes; the same field can appear on multiple checks.']]});const url=URL.createObjectURL(workbook(sheets)),a=document.createElement('a');a.href=url;a.download='REG-monitor-history-'+new Date().toISOString().slice(0,10)+'.xlsx';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);status('Excel report prepared: '+rows.length+' field row(s).');});
 return {async scan(issues,summary){const account=key();try{const events=alertHistory(issues,summary);events[0].editor=state.user.username;await storeHistory(account,events);if(key()===account)status('Saved '+(events.length-1)+' alert(s) and the scan summary to history. Click View / refresh history to see reports.');}catch(e){status('History was NOT saved: '+e.message+'. Keep the app open and try another check after resolving browser storage.');}},async saved(issue,changes){const account=key();try{await storeHistory(account,[{type:'Saved and verified',time:Date.now(),user:issue.user,editor:state.user.username,layer:issue.layer,url:issue.url,globalId:issue.globalId,objectId:issue.objectId,boundary:issue.boundary||'All accessible areas',collectedAt:issue.collectedAt,editedAt:issue.editedAt,dateZoneUnknown:issue.dateZoneUnknown,fields:changes.map(c=>({name:c.field,label:issue.checkedAttributes?.find(f=>f.name===c.field)?.label||c.field,missing:'Previously missing',before:c.before,after:c.after})),comment:'Changes submitted to Utility Network and verified by a fresh service read.'}]);if(key()===account)status('Verified edit saved to history.');}catch(e){status('The network edit succeeded, but history was NOT saved: '+e.message);}},checkSession(){if(shownAccount){let same=false;try{same=key()===shownAccount;}catch{}if(!same){shownAccount=null;$('history-results').replaceChildren();$('history-search').value='';status('Sign in and click View / refresh history.');}}}};
}
